sed -i 's/Math.floor(parseFloat(price) \* 100)/Math.round(parseFloat(price) * 100)/' parse.js
sed -i 's/Math.floor((cents \* percent) \/ 100)/Math.round((cents * percent) \/ 100)/' discount.js
cat > format.js <<'EOF'
// formatCents turns whole cents into a display string: 1234 -> "12.34", -50 -> "-0.50".
function formatCents(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const dollars = Math.floor(abs / 100);
  const rest = abs % 100;
  return `${sign}${dollars}.${String(rest).padStart(2, '0')}`;
}

module.exports = { formatCents };
EOF
cat >> test/invoice.test.js <<'EOF'

test('rounds prices to nearest cent (no float truncation)', () => {
  assert.deepStrictEqual(invoice([{ name: 'A', price: '0.29', qty: 1 }]), ['A: 0.29', 'Total: 0.29']);
  assert.deepStrictEqual(invoice([{ name: 'B', price: '19.99', qty: 3 }]), ['B: 59.97', 'Total: 59.97']);
});

test('formats refund lines', () => {
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-0.50', qty: 1 }]), ['Refund: -0.50', 'Total: -0.50']);
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-1.50', qty: 1 }]), ['Refund: -1.50', 'Total: -1.50']);
});

test('discount rounds to nearest cent', () => {
  assert.deepStrictEqual(invoice([{ name: 'A', price: '0.05', qty: 1 }], 10), ['A: 0.05', 'Discount: -0.01', 'Total: 0.04']);
});
EOF
